-- Read-only 0.1 C absolute-error histograms for pointwise median/P90/P95 approximations.
WITH p AS (SELECT CASE WHEN a.dateTime<1577836800 THEN 2019 ELSE 2020 END AS yr,a.outTemp AS y,r.temperature_c AS ref,(0.7886750170162296+0.9352562666974354*r.temperature_c+-0.20129399741209056*SIN(2*PI()*MOD(a.dateTime,86400)/86400)+-0.09305546547425936*COS(2*PI()*MOD(a.dateTime,86400)/86400)+-0.3075224035244028*SIN(2*PI()*(CASE WHEN a.dateTime<1577836800 THEN a.dateTime-1546300800 ELSE a.dateTime-1577836800 END)/(CASE WHEN a.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))+-1.496803043901965*COS(2*PI()*(CASE WHEN a.dateTime<1577836800 THEN a.dateTime-1546300800 ELSE a.dateTime-1577836800 END)/(CASE WHEN a.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))) AS model,CASE WHEN r.temperature_c=0 AND a.outTemp>=20 THEN 1 ELSE 0 END AS flagged,CASE WHEN a.outTemp<=0 THEN 1 ELSE 0 END AS freeze FROM loucka_reconstruction.archive a JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=a.dateTime WHERE a.dateTime>=1546300800 AND a.dateTime<1609459200 AND a.outTemp IS NOT NULL AND r.source_resolution='5min' AND r.quality_status='reference_only' AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=a.dateTime AND c.variable='outTemp')), e AS (SELECT yr,'all' grp,'direct' method,ABS(ref-y) err FROM p UNION ALL SELECT yr,'all','ols',ABS(model-y) FROM p UNION ALL SELECT yr,'nonflag','direct',ABS(ref-y) FROM p WHERE flagged=0 UNION ALL SELECT yr,'nonflag','ols',ABS(model-y) FROM p WHERE flagged=0 UNION ALL SELECT yr,'freeze_nonflag','direct',ABS(ref-y) FROM p WHERE flagged=0 AND freeze=1 UNION ALL SELECT yr,'freeze_nonflag','ols',ABS(model-y) FROM p WHERE flagged=0 AND freeze=1 UNION ALL SELECT yr,'flagged','direct',ABS(ref-y) FROM p WHERE flagged=1 UNION ALL SELECT yr,'flagged','ols',ABS(model-y) FROM p WHERE flagged=1) SELECT yr,grp,method,FLOOR(err*10) AS abs_error_decic_bucket,COUNT(*) AS n FROM e GROUP BY yr,grp,method,abs_error_decic_bucket ORDER BY yr,grp,method,abs_error_decic_bucket;
